from dataclasses import dataclass

import pytest


@dataclass
class Num:
    v: int


@dataclass
class Add:
    l: "Expr"
    r: "Expr"


@dataclass
class Mul:
    l: "Expr"
    r: "Expr"


Expr = Num | Add | Mul


def eval_expr(e: Expr) -> int:
    """Evaluate an expression tree of Num, Add, and Mul nodes to an int."""
    if isinstance(e, Num):
        return e.v
    if isinstance(e, Add):
        return eval_expr(e.l) + eval_expr(e.r)
    if isinstance(e, Mul):
        return eval_expr(e.l) * eval_expr(e.r)
    raise TypeError(f"unknown expression node: {e!r}")


def test_eval_num() -> None:
    assert eval_expr(Num(7)) == 7


def test_eval_add() -> None:
    assert eval_expr(Add(Num(2), Num(3))) == 5


def test_eval_mul() -> None:
    assert eval_expr(Mul(Num(4), Num(5))) == 20


def test_eval_nested() -> None:
    # (2 + 3) * (4 + 1) = 25
    e = Mul(Add(Num(2), Num(3)), Add(Num(4), Num(1)))
    assert eval_expr(e) == 25


def test_eval_negative_values() -> None:
    assert eval_expr(Add(Num(-3), Mul(Num(-2), Num(4)))) == -11


def test_eval_deep_left_chain() -> None:
    e: Expr = Num(1)
    for _ in range(100):
        e = Add(e, Num(1))
    assert eval_expr(e) == 101


def test_eval_unknown_node_raises() -> None:
    with pytest.raises(TypeError):
        eval_expr("not an expr")  # type: ignore[arg-type]
